PRAGMA foreign_keys=ON;
BEGIN IMMEDIATE;
CREATE TABLE schema_migration(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
INSERT INTO schema_migration VALUES(1,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
CREATE TABLE entity(id TEXT PRIMARY KEY CHECK(length(id)=36 AND id=lower(id) AND substr(id,9,1)='-' AND substr(id,14,1)='-' AND substr(id,19,1)='-' AND substr(id,24,1)='-' AND substr(id,15,1) GLOB '[1-8]' AND substr(id,20,1) GLOB '[89ab]' AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' AND length(replace(id,'-',''))=32),kind TEXT NOT NULL CHECK(kind IN ('building','business','place','entrance','menu','menu_item','public_facility','transit_agency','transit_route','transit_stop')),parent_id TEXT REFERENCES entity(id),CHECK(parent_id IS NULL OR parent_id!=id));
CREATE TABLE fact(id TEXT PRIMARY KEY,subject_id TEXT NOT NULL REFERENCES entity(id),property TEXT NOT NULL CHECK(length(trim(property))>0),knowledge TEXT NOT NULL CHECK(knowledge IN ('asserted','unknown','absent','not_applicable')),value_json TEXT CHECK(value_json IS NULL OR json_valid(value_json)),valid_from TEXT NOT NULL CHECK(julianday(valid_from) IS NOT NULL),valid_until TEXT NOT NULL CHECK(julianday(valid_until) IS NOT NULL AND julianday(valid_until)>julianday(valid_from)),CHECK((knowledge='asserted' AND value_json IS NOT NULL) OR (knowledge!='asserted' AND value_json IS NULL)));
CREATE INDEX fact_subject_property ON fact(subject_id,property);
CREATE TABLE source_snapshot(id TEXT PRIMARY KEY,source_id TEXT NOT NULL,source_version TEXT,data_extract_version TEXT NOT NULL CHECK(length(trim(data_extract_version))>0),raw_sha256 TEXT NOT NULL CHECK(length(raw_sha256)=64 AND raw_sha256 NOT GLOB '*[^0-9a-f]*'),license TEXT NOT NULL CHECK(length(trim(license))>0),attribution TEXT NOT NULL CHECK(length(trim(attribution))>0),fetched_at_utc TEXT NOT NULL CHECK(julianday(fetched_at_utc) IS NOT NULL),valid_until TEXT NOT NULL CHECK(julianday(valid_until) IS NOT NULL AND julianday(valid_until)>julianday(fetched_at_utc)));
CREATE TABLE fact_lineage(fact_id TEXT NOT NULL REFERENCES fact(id),snapshot_id TEXT NOT NULL REFERENCES source_snapshot(id),evidence_id TEXT NOT NULL,locator TEXT NOT NULL CHECK(length(trim(locator))>0),observed_at TEXT NOT NULL CHECK(julianday(observed_at) IS NOT NULL),verified_at TEXT NOT NULL CHECK(julianday(verified_at) IS NOT NULL AND julianday(verified_at)>=julianday(observed_at)),verification_method TEXT NOT NULL CHECK(length(trim(verification_method))>0 AND lower(trim(verification_method))!='unknown'),confidence_reason TEXT NOT NULL CHECK(length(trim(confidence_reason))>0 AND lower(trim(confidence_reason))!='unknown'),reviewer TEXT NOT NULL CHECK(length(trim(reviewer))>0),valid_until TEXT NOT NULL CHECK(julianday(valid_until) IS NOT NULL AND julianday(valid_until)>julianday(observed_at)),PRIMARY KEY(fact_id,evidence_id));
CREATE TABLE point(entity_id TEXT PRIMARY KEY REFERENCES entity(id),longitude REAL NOT NULL CHECK(longitude BETWEEN -180 AND 180),latitude REAL NOT NULL CHECK(latitude BETWEEN -90 AND 90),fact_id TEXT NOT NULL REFERENCES fact(id));
CREATE TRIGGER point_fact_insert BEFORE INSERT ON point WHEN NOT EXISTS(SELECT 1 FROM fact WHERE id=new.fact_id AND subject_id=new.entity_id AND property='coordinate' AND knowledge='asserted' AND json_extract(value_json,'$.longitude')=new.longitude AND json_extract(value_json,'$.latitude')=new.latitude AND json_extract(value_json,'$.crs')='EPSG:4326') BEGIN SELECT RAISE(ABORT,'point fact mismatch'); END;
CREATE TRIGGER point_fact_update BEFORE UPDATE ON point WHEN NOT EXISTS(SELECT 1 FROM fact WHERE id=new.fact_id AND subject_id=new.entity_id AND property='coordinate' AND knowledge='asserted' AND json_extract(value_json,'$.longitude')=new.longitude AND json_extract(value_json,'$.latitude')=new.latitude AND json_extract(value_json,'$.crs')='EPSG:4326') BEGIN SELECT RAISE(ABORT,'point fact mismatch'); END;
CREATE TRIGGER coordinate_value_guard BEFORE UPDATE OF subject_id,property,value_json,knowledge ON fact WHEN EXISTS(SELECT 1 FROM point WHERE fact_id=old.id) BEGIN SELECT RAISE(ABORT,'coordinate identity/value immutable while attached'); END;
CREATE VIRTUAL TABLE point_bbox USING rtree(rowid,min_lon,max_lon,min_lat,max_lat);
CREATE TRIGGER point_insert AFTER INSERT ON point BEGIN INSERT INTO point_bbox VALUES(new.rowid,new.longitude,new.longitude,new.latitude,new.latitude); END;
CREATE TRIGGER point_update AFTER UPDATE ON point BEGIN UPDATE point_bbox SET min_lon=new.longitude,max_lon=new.longitude,min_lat=new.latitude,max_lat=new.latitude WHERE rowid=old.rowid; END;
CREATE TRIGGER point_delete AFTER DELETE ON point BEGIN DELETE FROM point_bbox WHERE rowid=old.rowid; END;
CREATE TABLE search_document(id INTEGER PRIMARY KEY,fact_id TEXT UNIQUE NOT NULL REFERENCES fact(id),entity_id TEXT NOT NULL REFERENCES entity(id),name TEXT NOT NULL);
CREATE VIRTUAL TABLE search_fts USING fts5(name,content='search_document',content_rowid='id',tokenize='unicode61');
CREATE TRIGGER search_insert AFTER INSERT ON search_document BEGIN INSERT INTO search_fts(rowid,name) VALUES(new.id,new.name); END;
CREATE TRIGGER search_delete AFTER DELETE ON search_document BEGIN INSERT INTO search_fts(search_fts,rowid,name) VALUES('delete',old.id,old.name); END;
CREATE TRIGGER search_update AFTER UPDATE ON search_document BEGIN INSERT INTO search_fts(search_fts,rowid,name) VALUES('delete',old.id,old.name); INSERT INTO search_fts(rowid,name) VALUES(new.id,new.name); END;
CREATE TABLE pack_metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
COMMIT;
